//! Instruction code generator module
//! Generates Rust code from parsed instruction specifications

use anyhow::{Context, Result};
use std::collections::HashMap;

use super::parser::{Architecture, InstructionSpec, EncodingFormat};

/// Generate architecture-specific Rust code from instruction specs
pub fn generate_arch_code(arch: Architecture, specs: &[InstructionSpec]) -> Result<String> {
    let arch_name = format!("{:?}", arch).to_lowercase();
    
    let mut output = String::new();
    
    // Header comment
    output.push_str(&format!(
        "// Auto-generated from JSON specs for {}\n",
        arch_name.to_uppercase()
    ));
    output.push_str("// DO NOT EDIT - Generated by codegen-gen\n\n");
    
    // Import statements
    output.push_str("use crate::codegen::shared::instruction_traits::*;\n\n");
    
    // Generate each instruction
    for spec in specs {
        let generated = generate_instruction_code(spec)?;
        output.push_str(&generated);
        output.push_str("\n");
    }
    
    // Register encoder implementation
    output.push_str("\n/// All instructions for this architecture\n");
    output.push_str("pub static ALL_INSTRUCTIONS: &[Instruction] = &[\n");
    for spec in specs {
        let const_name = format!("{}_INSTRUCTION", spec.name.to_uppercase());
        output.push_str(&format!("    &{},\n", const_name));
    }
    output.push_str("];\n\n");
    
    Ok(output)
}

/// Generate Rust code for a single instruction
fn generate_instruction_code(spec: &InstructionSpec) -> Result<String> {
    let name_upper = spec.name.to_uppercase();
    
    let mut output = String::new();
    
    // Documentation comment
    output.push_str(&format!("/// {} - {}", spec.name, spec.description));
    
    // Add flags if defined
    if let Some(semantics) = &spec.semantics {
        if let Some(flags) = &semantics.flags_modified {
            output.push_str("\n/// Modified flags: ");
            output.push_str(&flags.join(", "));
        }
    }
    
    output.push_str("\n///\n");
    output.push_str(&format!("/// Operand pattern: {}", spec.encoding_spec.default_format.clone().unwrap_or_else(|| "varies".to_string())));
    output.push_str("\n#[derive(Debug, Clone)]\n");
    output.push_str(&format!("pub const {}: Instruction = Instruction {{\n", name_upper));
    
    // Name field
    output.push_str(&format!("    name: \"{}\",\n", spec.name));
    
    // Description
    output.push_str(&format!("    description: \"{}\",\n", spec.description));
    
    // Encoding formats
    output.push_str("    encodings: vec![\n");
    for (idx, fmt) in spec.encoding_spec.formats.iter().enumerate() {
        if idx > 0 {
            output.push_str(",\n");
        }
        output.push_str("        Encoding {\n");
        
        // Pattern name
        let pattern_name = fmt.operand_pattern.replace("/", "_").replace(' ', "_");
        output.push_str(&format!("            pattern: InstructionPattern::{},\n", pattern_name));
        
        // Opcode bytes
        output.push_str("            opcode_bytes: vec![");
        for (i, byte) in fmt.opcode.iter().enumerate() {
            if i > 0 {
                output.push_str(", ");
            }
            output.push_str(&format!("0x{:02X}", byte));
        }
        output.push_str("],\n");
        
        // ModRM requirement
        if fmt.modrm_required {
            output.push_str("            modrm_required: true,\n");
        }
        
        // REX prefix (x86 only)
        if fmt.rex_prefix {
            output.push_str("            rex_prefix: true,\n");
        }
        
        // Escape bytes
        if let Some(escape) = &fmt.escape_bytes {
            output.push_str("            escape_bytes: Some(vec![");
            for (i, byte) in escape.iter().enumerate() {
                if i > 0 {
                    output.push_str(", ");
                }
                output.push_str(&format!("0x{:02X}", byte));
            }
            output.push_str("]),\n");
        }
        
        // Addressing mode
        if let Some(addr_mode) = &fmt.addressing_mode {
            output.push_str(&format!("            addressing_mode: Some(\"{}\".to_string()),\n", addr_mode));
        }
        
        // Extra bytes flag
        if fmt.extra_bytes {
            output.push_str("            extra_bytes: true,\n");
        }
        
        output.push_str("        }\n");
    }
    
    output.push_str("    ],\n");
    
    // Semantics
    output.push_str("    semantics: InstructionSemantics {\n");
    
    if let Some(semantics) = &spec.semantics {
        if let Some(effect) = &semantics.effect {
            output.push_str(&format!("        effect: Some(\"{}\".to_string()),\n", effect));
        } else {
            output.push_str("        effect: None,\n");
        }
        
        if let Some(flags) = &semantics.flags_modified {
            output.push_str("        flags_modified: vec![");
            for (i, flag) in flags.iter().enumerate() {
                if i > 0 {
                    output.push_str(", ");
                }
                output.push_str(&format!("\"{}\"", flag));
            }
            output.push_str("],\n");
        } else {
            output.push_str("        flags_modified: vec![],\n");
        }
        
        if let Some(exceptions) = &semantics.exceptions {
            output.push_str("        exceptions: Some(vec![");
            for (i, exc) in exceptions.iter().enumerate() {
                if i > 0 {
                    output.push_str(", ");
                }
                output.push_str(&format!("\"{}\"", exc));
            }
            output.push_str("]),\n");
        } else {
            output.push_str("        exceptions: None,\n");
        }
    } else {
        output.push_str("        effect: None,\n");
        output.push_str("        flags_modified: vec![],\n");
        output.push_str("        exceptions: None,\n");
    }
    
    output.push_str("    },\n");
    
    // Close constant definition
    output.push_str("};\n\n");
    
    // Generate encoder implementation
    output.push_str(&generate_encoder_implementation(spec)?);
    
    Ok(output)
}

/// Generate encoder implementation for an instruction
fn generate_encoder_implementation(spec: &InstructionSpec) -> Result<String> {
    let mut output = String::new();
    
    output.push_str(&format!(
        "/// Encoder implementation for {} instruction\n",
        spec.name
    ));
    output.push_str(&format!(
        "impl InstructionEncoder for {}Instruction {{\n",
        spec.name.to_uppercase()
    ));
    
    output.push_str("    fn encode(\n");
    output.push_str("        &self,\n");
    output.push_str("        operands: &[Operand],\n");
    output.push_str("        _mode: AssemblyMode,\n");
    output.push_str("    ) -> Result<Vec<u8>> {\n");
    
    // Select best encoding based on operands
    output.push_str("        // Select appropriate encoding based on operand types\n");
    output.push_str("        let encoding = self.select_encoding(operands)?;\n\n");
    
    // Generate encoding-specific code
    for (idx, fmt) in spec.encoding_spec.formats.iter().enumerate() {
        if idx > 0 {
            output.push_str("        \n    ");
        }
        
        let pattern_name = fmt.operand_pattern.replace("/", "_").replace(' ', "_");
        output.push_str(&format!(
            "if matches!(encoding.pattern, InstructionPattern::{}) {{\n",
            pattern_name
        ));
        output.push_str("            // TODO: Implement actual encoding logic\n");
        
        match idx {
            0 => {
                // First/default encoding - provide example
                output.push_str("            let mut result = Vec::new();\n");
                output.push_str("            result.extend_from_slice(&encoding.opcode_bytes);\n");
                output.push_str("            \n");
                
                if fmt.modrm_required {
                    output.push_str("            // Encode ModR/M byte\n");
                    output.push_str("            if operands.len() >= 2 {\n");
                    output.push_str("                let modrm = encode_modrm(0, 1); // Placeholder\n");
                    output.push_str("                result.push(modrm);\n");
                    output.push_str("            }\n");
                }
                
                if fmt.extra_bytes {
                    output.push_str("            // Handle immediate bytes\n");
                    output.push_str("            if let Some(imm) = operands.get(1).and_then(|o| o.immediate_value()) {\n");
                    output.push_str("                result.extend_from_slice(&imm.to_le_bytes());\n");
                    output.push_str("            }\n");
                }
                
                output.push_str("            Ok(result)\n");
            }
            _ => {
                output.push_str(format!(
                    "            // TODO: Implement variant {} encoding\n",
                    idx
                ).as_str());
                output.push_str("            unimplemented!(\"Variants not yet implemented\")\n");
            }
        }
        
        output.push_str("        };");
    }
    
    output.push_str("\n    };\n");
    output.push_str("}\n");
    
    Ok(output)
}

// Helper function placeholder for ModR/M encoding
// Will be moved to shared layer when Instruction types are defined
fn encode_modrm(_lhs: u8, _rhs: u8) -> u8 {
    0xC0 // Default: reg,reg encoding
}
